import re
from ta_messaging.submodule_ute_common_abstract_core.aliases_registry import aliases_registry
from ute_common_abstract_core.network_elem_identification import LteNetworkElement
from ta_messaging.message_manager import MessageManager
from ta_messaging.testenv import TestEnv, _get_mme_ip_by_wts_id, _get_enb_ip_by_wts_id,\
    get_tshark_procotol_names_matching_string
from ute_common_abstract_core.network_elem_identification import UeIdentification, \
    MmeIdentification, AmfIdentification, EnbIdentification, FifthGenerationNetworkElement, GnbIdentification, EndpointsIp
from ta_messaging.testenv import DYNAMIC_SOURCE_SUFFIX

DYNAMIC_UE_SOURCE_REGEXP = re.compile(r'(\D)\_(\d+)$')
DYNAMIC_CELL_SOURCE_REGEXP = re.compile(r'(\D)\_(\d+)\_(\d+)$')
DYNAMIC_SOURCE_REGEXPS = {'UE': DYNAMIC_UE_SOURCE_REGEXP,
                          'CELL': DYNAMIC_CELL_SOURCE_REGEXP}

NEW_AP_IMPLEMENTATION = True


def check_new_ap_implementation():
    """
    Enables or disables new ap implementation for legacy devices
    """
    return True if NEW_AP_IMPLEMENTATION is True else False


def disable_new_ap_implementation_emergency_solution():
    """
    Allows to temporary disable new ap implementation for legacy sources
    """
    global NEW_AP_IMPLEMENTATION
    NEW_AP_IMPLEMENTATION = False


class AliasFactory(object):

    DEVICES_IDENTIFICATION = {
        'UE': UeIdentification,
        'MME': MmeIdentification,
        'AMF': AmfIdentification,
        'ENB': EnbIdentification,
        'GNB': GnbIdentification
    }

    def create_ue_alias(self, alias, ue_id, id_type):
        """
        Create abstract identification of UE (alias) from 'physical' identification

        example::

            create_ue_alias('UE_1', ue_id=101, id_type='wts')

        Required (temporally) for binding this library with other libraries (like ute_wtssim)
        directly using tool-specific-identification of UE

        :param alias: abstract identification of UE that will be used later in script
        :param ue_id: physical/tool-specific identification of UE
        :param id_type: type of id (like 'wts')
        :return: None
        """
        # TestEnv knows what variants are available and what are id validation rules for that variant
        TestEnv().validate_message_source_variant(network_elem_type='UE', variant=id_type)
        ue_id = TestEnv().validate_variant_id(network_elem_type='UE', variant=id_type, id_of_variant=ue_id)
        MessageManager()

        ue_identification = TestEnv().create_msg_src_id(identifiers=[('alias', alias), (id_type, ue_id)],
                                                        network_elem_type='UE', variant=id_type,
                                                        specific_for_tool=id_type)
        #########################################################################################################
        # to allow for having 2 entries for UE-alias inside common aliases_registry (which checks uniqueness)
        #
        # Require Ue          UE_ALIAS_1    capabilities=CAT6
        # Create UE alias     UE_ALIAS_1    ue_id=9            id_type=wts
        #
        # Since 'Create UE alias' is temporary solution required for messaging we need both keywords.
        # And since we want to keep all aliases in common aliases_registry:
        #   we need following trick to split logically same alias into two:
        #   1) UE_ALIAS_1                 - first line registers LteUe object under this alias
        #   2) UE_ALIAS_1__identification - second line registers LteNetworkElement(UeIdentification) object
        ########################################################################################################
        alias_for_ue_identification = alias + "__identification"
        aliases_registry()[alias_for_ue_identification] = LteNetworkElement(ue_identification)

    def create_ues_alias(self, alias, id_type):
        """
        Create abstract identification of UE (alias) from 'physical' identification

        example::

            create_ues_alias('UE_1', id_type='wts')

        Required (temporally) for binding this library with other libraries (like ute_wtssim)
        directly using tool-specific-identification of UE

        :param alias: abstract identification of UE that will be used later in script
        :param id_type: type of id (like 'wts' or wts_5g)
        :return: None
        """

        # TestEnv knows what variants are available and what are id validation rules for that variant
        id_type = id_type + DYNAMIC_SOURCE_SUFFIX
        TestEnv().validate_message_source_variant(network_elem_type='UE', variant=id_type)
        ue_id = TestEnv().validate_variant_id(network_elem_type='UE', variant=id_type, id_of_variant=None)
        MessageManager()

        ue_identification = TestEnv().create_msg_src_id(identifiers=[('alias', alias), (id_type, ue_id)],
                                                        network_elem_type='UE', variant=id_type,
                                                        specific_for_tool=id_type)
        #########################################################################################################
        # to allow for having 2 entries for UE-alias inside common aliases_registry (which checks uniqueness)
        #
        # Require Ue          UE_ALIAS_1    capabilities=CAT6
        # Create UE alias     UE_ALIAS_1    ue_id=9            id_type=wts
        #
        # Since 'Create UE alias' is temporary solution required for messaging we need both keywords.
        # And since we want to keep all aliases in common aliases_registry:
        #   we need following trick to split logically same alias into two:
        #   1) UE_ALIAS_1                 - first line registers LteUe object under this alias
        #   2) UE_ALIAS_1__identification - second line registers LteNetworkElement(UeIdentification) object
        ########################################################################################################
        alias_for_ue_identification = alias + "__identification"
        ne_element_class = _map_technology_to_identification(id_type)
        aliases_registry()[alias_for_ue_identification] = ne_element_class(ue_identification)

    def create_ue_group_aliases(self, alias, start_ue_id, stop_ue_id, id_type):
        """
        Create abstract identification of UE (alias) from 'physical' identification

        example::

            create_ue_group_aliases('UE_1', start_ue_id=101, stop_ue_id=105, id_type='wts')

        Required (temporally) for binding this library with other libraries (like ute_wtssim)
        directly using tool-specific-identification of UE

        :param alias: abstract identification of UE that will be used later in script
        :param start_ue_id: physical/tool-specific identification of UE
        :param stop_ue_id: physical/tool-specific identification of UE
        :param id_type: type of id (like 'wts')
        :return: None
        """
        TestEnv().validate_message_source_variant(network_elem_type='UE_GROUP', variant=id_type)
        ue_group_ids = TestEnv().validate_variant_id(network_elem_type='UE_GROUP', variant=id_type,
                                                     id_of_variant=(start_ue_id, stop_ue_id))
        start_ue_id = ue_group_ids[0]
        stop_ue_id = ue_group_ids[1]
        ue_id_range = list(range(start_ue_id, stop_ue_id + 1))
        for index, ue_id in enumerate(ue_id_range):
            single_alias = alias + "_{}".format(index + 1)
            ue_identification = UeIdentification.from_type_id_pairs(identifiers=[('alias', single_alias),
                                                                                 (id_type, ue_id)],
                                                                    specific_for_tool=id_type)
        #########################################################################################################
        # to allow for having 2 entries for UE-alias inside common aliases_registry (which checks uniqueness)
        #
        # Require Ue          UE_ALIAS_1    capabilities=CAT6
        # Create UE alias     UE_ALIAS_1    ue_id=9            id_type=wts
        #
        # Since 'Create UE alias' is temporary solution required for messaging we need both keywords.
        # And since we want to keep all aliases in common aliases_registry:
        #   we need following trick to split logically same alias into two:
        #   1) UE_ALIAS_1                 - first line registers LteUe object under this alias
        #   2) UE_ALIAS_1__identification - second line registers LteNetworkElement(UeIdentification) object
        ########################################################################################################
            alias_for_ue_identification = single_alias + "__identification"
            aliases_registry()[alias_for_ue_identification] = LteNetworkElement(ue_identification)
        # group_ue_identification = UeIdentification.from_type_id_pairs(identifiers=[('alias', alias), (id_type, [start_ue_id, stop_ue_id])],
        #                                                               specific_for_tool=id_type)
        MessageManager()  # TODO ue_group_ids should be tuple not list
        TestEnv().create_msg_src_id(identifiers=[('alias', alias), (id_type, ue_group_ids)],
                                    network_elem_type='UE_GROUP', variant=id_type,
                                    specific_for_tool=id_type)

    def create_enb_alias(self, alias, enb_id, id_type):
        """
        Create abstract identification of eNB (alias) from 'physical' identification

        example::

            create_enb_alias('ENB_1', enb_id=1, id_type='wts')

        Required (temporally) for binding this library with other libraries (like ute_wtssim)
        directly using tool-specific-identification of eNB

        :param alias: abstract identification of eNB that will be used later in script
        :param enb_id: physical/tool-specific identification of eNB
        :param id_type: type of id (like 'wts')
        :return: None
        """
        TestEnv().validate_message_source_variant(network_elem_type='ENB', variant=id_type)
        enb_id = TestEnv().validate_variant_id(network_elem_type='ENB', variant=id_type, id_of_variant=enb_id)
        if check_new_ap_implementation() and id_type in ['wts', 'real']:
            if id_type == 'real':
                from ta_messaging.message_sources.message_sources_tshark_based import X2RealEnbMessageSource
                X2RealEnbMessageSource.enable_ip_capturing_via_admin()
                self.create_ap_protocols_alias('ENB', alias, {'ip': enb_id})
            if id_type == 'wts':
                self.create_ap_protocols_alias('ENB', alias, {'wts_id': enb_id})
            return
        MessageManager()
        enb_identification = TestEnv().create_msg_src_id(identifiers=[('alias', alias), (id_type, enb_id)],
                                                         network_elem_type='ENB', variant=id_type,
                                                         specific_for_tool=id_type)
        aliases_registry()[alias] = LteNetworkElement(enb_identification)

    def create_mme_alias(self, alias, mme_id, id_type):
        """
        Create abstract identification of MME (alias) from 'physical' identification

        example::

            create_mme_alias('MME_2', mme_id=12, id_type='wts')

        Required (temporally) for binding this library with other libraries (like ute_wtssim)
        directly using tool-specific-identification of MME

        :param alias: abstract identification of MME that will be used later in script
        :param mme_id: physical/tool-specific identification of MME
        :param id_type: type of id (like 'wts')
        :return: None
        """
        TestEnv().validate_message_source_variant(network_elem_type='MME', variant=id_type)
        mme_id = TestEnv().validate_variant_id(network_elem_type='MME', variant=id_type, id_of_variant=mme_id)
        if check_new_ap_implementation() and id_type == 'wts':
            self.create_ap_protocols_alias('MME', alias, {'wts_id': mme_id})
            return
        MessageManager()
        mme_identification = TestEnv().create_msg_src_id(identifiers=[('alias', alias), (id_type, mme_id)],
                                                         network_elem_type='MME', variant=id_type,
                                                         specific_for_tool=id_type)
        aliases_registry()[alias] = LteNetworkElement(mme_identification)

    def create_ap_protocols_alias(self, device, alias, ids):
        """
        Create abstract identification of MME (alias) from 'physical' identification

        example::

            create_mme_alias('MME_2', mme_id=12, id_type='wts')

        Required (temporally) for binding this library with other libraries (like ute_wtssim)
        directly using tool-specific-identification of MME

        :param alias: abstract identification of MME that will be used later in script
        :param mme_id: physical/tool-specific identification of MME
        :param id_type: type of id (like 'wts')
        :return: None
        """
        MessageManager()
        TestEnv().create_msg_src_id(identifiers=[('alias', 'AP_DEVICE'), ('all', None)],
                                    network_elem_type='AP_DEVICE', variant='all',
                                    specific_for_tool='all')
        device = str(device).upper()
        assert device in list(AliasFactory.DEVICES_IDENTIFICATION.keys()),\
            'Only supported devices: {}'.format(list(AliasFactory.DEVICES_IDENTIFICATION.keys()))
        if 'wts_id' in ids:
            ip_getter = _map_device_type_to_wts_id_getter(device)
            ip = ip_getter(wts_id=ids['wts_id'])
        else:
            ip = ids['ip']
        identification = AliasFactory.DEVICES_IDENTIFICATION[device].\
            from_type_id_pairs(identifiers=[('alias', alias), ('ip', EndpointsIp([ip]))])
        aliases_registry()[alias] = _map_technology_to_identification(device)(identification)

    def enable_mirroring_for_alias(self, alias):
        """
        Starts additional message source for already existing alias (5G) or enable packet mirroring (4G)
        """
        assert str(alias) in aliases_registry(), 'Alias: {} must be created before using the keyword'.format(alias)
        identification = aliases_registry()[alias].network_elem_identifier

        assert isinstance(identification, EnbIdentification) or isinstance(identification, GnbIdentification),\
            'Identification: {} for alias: {} must be of types: [{}]'.format(identification, alias,
                                                                             [EnbIdentification, GnbIdentification])
        TRANSFER_PROTOCOL = 'SYSCOM'  # also supports the legacy SCTP
        if isinstance(identification, GnbIdentification):
            id = {'id': GnbIdentification, 'ip': identification['ip']}
            assert len(id['ip']) == 1, 'only single IP accepted in identification: {}'.format(id['ip'])
            id['ip'] = list(id['ip'])[0]
            platform = TestEnv().get_gnb_platform_type(user='toor4nsn', password='oZPS0POrRieRtu', ip=id['ip'])
            id['platform'] = platform
            if platform == 'VRAN':
                TestEnv().create_msg_src_id(identifiers=[('alias', '5G_VRAN_INTERNAL_{}'.format(id['ip'])), ('id', id)],
                                            network_elem_type='5G_VRAN_INTERNAL', variant='id',
                                            specific_for_tool='id')
            else:
                if TRANSFER_PROTOCOL != 'SYSCOM':
                    TestEnv().create_msg_src_id(identifiers=[('alias', '5G_INTERNAL_{}'.format(id['ip'])), ('id', id)],
                                                network_elem_type='5G_INTERNAL', variant='id',
                                                specific_for_tool='id')
                else:
                    # to allow also xn/ng parsing from internal
                    TestEnv().create_msg_src_id(
                        identifiers=[('alias', '5G_INTERNAL_{}'.format(id['ip'])), ('id', id)],
                        network_elem_type='5G_INTERNAL_NO_F1E1', variant='id',
                        specific_for_tool='id')

                    if not len(get_tshark_procotol_names_matching_string('itf')):
                        from robot.api import logger
                        logger.warn('MCSHARK is not installed! '
                                    'E1/F1 messages will not be captured.\n'
                                    'In reservation/SR use e.g. TOOLS_PROFILE_TTI_LEGACY tag or '
                                    'install manually using:\n'
                                    'https://artifactory-hz1.int.net.nokia.com/artifactory/'
                                    'wslte5g_plugins-local/tools/install_wslte_plugins.bash')
                    else:
                        TestEnv().create_msg_src_id(
                            identifiers=[('alias', '5G_INTERNAL_{}'.format(id['ip'])), ('id', id)],
                            network_elem_type='5G_INTERNAL_F1AP', variant='id',
                            specific_for_tool='id')

                        TestEnv().create_msg_src_id(
                            identifiers=[('alias', '5G_INTERNAL_{}'.format(id['ip'])), ('id', id)],
                            network_elem_type='5G_INTERNAL_E1AP', variant='id',
                            specific_for_tool='id')

        elif isinstance(identification, EnbIdentification):
            raise Exception('Not yet implemented for identification: {}'.format(EnbIdentification))

    def create_cell_alias(self, alias, cell_id, cell_type, enb_id=None, enb_type=None):
        """
         Create abstract identification of CELL (alias) from 'physical' identification

         example::

             create_cell_alias('CELL_1_2', cell_id=12, cell_id_type='wts_cell_id', enb_id=12, enb_id_type='wts_enb_id')

         Required (temporally) for binding this library with other libraries (like ute_wtssim)
         directly using tool-specific-identification of MME

         :param alias: abstract identification of cell that will be used later in script
         :param cell_id: physical/tool-specific identification of cell
         :param cell_type: type of id (like 'wts_cell_id')
         :param enb_id: physical/tool-specific identification of enb
         :param enb_type: type of id (like 'wts_enb_id')
         :return: None
        """
        if enb_id is None and enb_type is None:
            tool_sepcific_cell_id = cell_id
            id_type = cell_type
        else:
            tool_sepcific_cell_id = {'enb_id': enb_id, 'cell_id': cell_id}
            cell_type_suffix = cell_type[-5:]
            enb_type_suffix = enb_type[-4:]
            assert cell_type_suffix == "_cell", "cell_type must have '_cell' suffix"
            assert enb_type_suffix == "_enb", "enb_type must have '_enb' suffix"
            cell_type = cell_type[:-5]
            enb_type = enb_type[:-4]
            assert cell_type == enb_type,\
                "cell_type and enb_type must be the same kind e.g. cell_type=wts_cell and enb_type=wts_enb"
            id_type = cell_type

        TestEnv().validate_message_source_variant(network_elem_type='CELL', variant=id_type)
        cell_id = TestEnv().validate_variant_id(network_elem_type='CELL', variant=id_type,
                                                id_of_variant=tool_sepcific_cell_id)
        alias_for_cell_identification = alias + "__identification"
        MessageManager()
        cell_identification = TestEnv().create_msg_src_id(identifiers=[('alias', alias), (id_type, cell_id)],
                                                          network_elem_type='CELL', variant=id_type,
                                                          specific_for_tool=id_type)

        aliases_registry()[alias_for_cell_identification] = LteNetworkElement(cell_identification)

    def create_cells_alias(self, alias, cells_type):
        """
         Create abstract identification of CELL (alias) from 'physical' identification

         example::

             create_cell_alias('5GCELL','wts_5g')

         Required (temporally) for binding this library with other libraries (like ute_wtssim)
         directly using tool-specific-identification of MME

         :param alias: abstract identification of cell that will be used later in script
         :param cell_types: type of id (like 'wts_5g_cell')
         :return: None
        """
        tool_specific_cell_id = None
        id_type = cells_type + DYNAMIC_SOURCE_SUFFIX
        allowed_types = ['wts', 'wts_5g']
        assert cells_type in allowed_types, "cells_type allowed only from range: {}".format(allowed_types)

        TestEnv().validate_message_source_variant(network_elem_type='CELL', variant=id_type)
        cell_id = TestEnv().validate_variant_id(network_elem_type='CELL', variant=id_type,
                                                id_of_variant=tool_specific_cell_id)
        alias_for_cell_identification = alias + "__identification"
        MessageManager()
        cell_identification = TestEnv().create_msg_src_id(identifiers=[('alias', alias), (id_type, cell_id)],
                                                          network_elem_type='CELL', variant=id_type,
                                                          specific_for_tool=id_type)
        ne_element_class = _map_technology_to_identification(cells_type)
        aliases_registry()[alias_for_cell_identification] = ne_element_class(cell_identification)

    def shutdown(self):
        """
        Shutdown all stuff started by alias factory
        """
        MessageManager().stop()


__alias_factory = None


def _map_technology_to_identification(id_type):
    devices_identifiers_5g = ['5g', 'gnb', 'amf']
    if str(id_type).lower() in devices_identifiers_5g:
        return FifthGenerationNetworkElement
    else:
        return LteNetworkElement


def _map_device_type_to_wts_id_getter(device):
    DEVICE_TYPE_ID_FUNC = {'MME': _get_mme_ip_by_wts_id,
                           'ENB': _get_enb_ip_by_wts_id,
                           'GNB': _get_enb_ip_by_wts_id,
                           'AMF': _get_mme_ip_by_wts_id}
    return DEVICE_TYPE_ID_FUNC[str(device).upper()]


def get_alias_factory():
    """get alias factory singleton instance"""
    global __alias_factory
    if __alias_factory is None:
        __alias_factory = AliasFactory()
    return __alias_factory
